import{H as e,Q as t,R as n,b as r,h as i,t as a,v as o,x as s,y as c}from"./app-C7UVirDn.js";import"./sync_en_04-CUFBh7WD.js";import"./pipe2-D2NcODyi.js";import"./data-sync-new-BR08zBXF.js";var l=JSON.parse(`{"path":"/UserGuide/latest/User-Manual/Data-Sync_apache.html","title":"Data Sync","lang":"en-US","frontmatter":{"description":"Data Sync Data synchronization is a typical requirement in industrial Internet of Things (IoT). Through data synchronization mechanisms, it is possible to achieve data sharing b...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Data Sync\\",\\"image\\":[\\"https://iotdb.apache.org/img/data-sync-new.png\\",\\"https://iotdb.apache.org/img/Data-Sync02.png\\",\\"https://iotdb.apache.org/img/pipe1.jpg\\",\\"https://iotdb.apache.org/img/pipe2.jpg\\",\\"https://iotdb.apache.org/img/sync_en_03.png\\",\\"https://iotdb.apache.org/img/sync_en_04.png\\"],\\"dateModified\\":\\"2026-08-12T04:00:42.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://iotdb.apache.org/UserGuide/latest/User-Manual/Data-Sync_apache.html"}],["meta",{"property":"og:site_name","content":"IoTDB Website"}],["meta",{"property":"og:title","content":"Data Sync"}],["meta",{"property":"og:description","content":"Data Sync Data synchronization is a typical requirement in industrial Internet of Things (IoT). Through data synchronization mechanisms, it is possible to achieve data sharing b..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://iotdb.apache.org/img/data-sync-new.png"}],["meta",{"property":"og:locale","content":"en-US"}],["meta",{"property":"og:locale:alternate","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-12T04:00:42.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-12T04:00:42.000Z"}],["link",{"rel":"alternate","hreflang":"zh-cn","href":"https://iotdb.apache.org/zh/UserGuide/latest/User-Manual/Data-Sync_apache.html"}]]},"git":{"createdTime":1696932526000,"updatedTime":1786507242000,"contributors":[{"name":"wanghui42","username":"wanghui42","email":"105700158+wanghui42@users.noreply.github.com","commits":2,"url":"https://github.com/wanghui42"},{"name":"Haonan","username":"Haonan","email":"hhaonan@outlook.com","commits":1,"url":"https://github.com/Haonan"},{"name":"CritasWang","username":"CritasWang","email":"critas@outlook.com","commits":3,"url":"https://github.com/CritasWang"},{"name":"Caideyipi","username":"Caideyipi","email":"87789683+Caideyipi@users.noreply.github.com","commits":1,"url":"https://github.com/Caideyipi"},{"name":"shuwenwei","username":"shuwenwei","email":"55970239+shuwenwei@users.noreply.github.com","commits":1,"url":"https://github.com/shuwenwei"},{"name":"mal117","username":"mal117","email":"107627937+mal117@users.noreply.github.com","commits":4,"url":"https://github.com/mal117"},{"name":"shi10lin0s","username":"shi10lin0s","email":"50943998+shi10lin0s@users.noreply.github.com","commits":1,"url":"https://github.com/shi10lin0s"},{"name":"W1y1r","username":"W1y1r","email":"150988475+W1y1r@users.noreply.github.com","commits":7,"url":"https://github.com/W1y1r"},{"name":"Mister-Hope","username":"Mister-Hope","email":"mister-hope@outlook.com","commits":1,"url":"https://github.com/Mister-Hope"},{"name":"leto-b","username":"leto-b","email":"bingqian.bai@timecho.com","commits":15,"url":"https://github.com/leto-b"},{"name":"leto-bbq","username":"leto-bbq","email":"bingqian.bai@timecho.com","commits":2,"url":"https://github.com/leto-bbq"}]},"readingTime":{"minutes":17.12,"words":5137},"filePathRelative":"UserGuide/latest/User-Manual/Data-Sync_apache.md","autoDesc":true}`),u={name:`Data-Sync_apache.md`};function d(a,l,u,d,f,p){let m=e(`RouteLink`);return n(),o(`div`,null,[l[12]||=c(`<h1 id="data-sync" tabindex="-1"><a class="header-anchor" href="#data-sync"><span>Data Sync</span></a></h1><p>Data synchronization is a typical requirement in industrial Internet of Things (IoT). Through data synchronization mechanisms, it is possible to achieve data sharing between IoTDB, and to establish a complete data link to meet the needs for internal and external network data interconnectivity, edge-cloud synchronization, data migration, and data backup.</p><h2 id="_1-function-overview" tabindex="-1"><a class="header-anchor" href="#_1-function-overview"><span>1. Function Overview</span></a></h2><h3 id="_1-1-data-synchronization" tabindex="-1"><a class="header-anchor" href="#_1-1-data-synchronization"><span>1.1 Data Synchronization</span></a></h3><p>A data synchronization task consists of three stages:</p><figure><img src="/img/data-sync-new.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><ul><li>Source Stage：This part is used to extract data from the source IoTDB, defined in the source section of the SQL statement.</li><li>Process Stage：This part is used to process the data extracted from the source IoTDB, defined in the processor section of the SQL statement.</li><li>Sink Stage：This part is used to send data to the target IoTDB, defined in the sink section of the SQL statement.</li></ul><p>By declaratively configuring the specific content of the three parts through SQL statements, flexible data synchronization capabilities can be achieved. Currently, data synchronization supports the synchronization of the following information, and you can select the synchronization scope when creating a synchronization task (the default is data.insert, which means synchronizing newly written data):</p><table style="text-align:left;"><tbody><tr><th>Synchronization Scope</th><th>Synchronization Content </th><th>Description</th></tr><tr><td colspan="2">all</td><td>All scopes</td></tr><tr><td rowspan="2">data（Data）</td><td>insert</td><td>Synchronize newly written data</td></tr><tr><td>delete</td><td>Synchronize deleted data</td></tr><tr><td rowspan="3">schema</td><td>database</td><td>Synchronize database creation, modification or deletion operations</td></tr><tr><td>timeseries</td><td>Synchronize the definition and attributes of time series</td></tr><tr><td>TTL</td><td>Synchronize the data retention time</td></tr><tr><td>auth</td><td>-</td><td>Synchronize user permissions and access control</td></tr></tbody></table><h3 id="_1-2-functional-limitations-and-instructions" tabindex="-1"><a class="header-anchor" href="#_1-2-functional-limitations-and-instructions"><span>1.2 Functional limitations and instructions</span></a></h3><ol><li>The schema and auth synchronization functions have the following limitations:</li></ol><ul><li><p>When using schema synchronization, it is required that the consensus protocol for <code>Schema region</code> and <code>ConfigNode</code> must be the default ratis protocol. This means that the <code>iotdb-system.properties</code> configuration file should contain the settings <code>config_node_consensus_protocol_class=org.apache.iotdb.consensus.ratis.RatisConsensus</code> and <code>schema_region_consensus_protocol_class=org.apache.iotdb.consensus.ratis.RatisConsensus</code>. If these are not specified, the default ratis protocol is used.</p></li><li><p>To prevent potential conflicts, please disable the automatic creation of schema on the receiving end when enabling schema synchronization. This can be done by setting the <code>enable_auto_create_schema</code> configuration in the <code>iotdb-system.properties</code> file to false.</p></li><li><p>When schema synchronization is enabled, the use of custom plugins is not supported.</p></li><li><p>During data synchronization tasks, please avoid performing any deletion operations to prevent inconsistent states between the two ends.</p></li></ul><ol start="2"><li>Pipe Permission Control Specifications</li></ol><ul><li><p>When creating a pipe, a username and password can be specified for the extraction/write‑back plugins. If the password is incorrect, creation is prohibited. If not specified, the current user is used for synchronization by default.</p></li><li><p>During data/metadata synchronization, filtering is first performed according to the path pattern (pattern/path) configured in the Pipe, followed by authentication based on the user’s read permissions:</p><ul><li>If the permission scope is greater than or equal to the write path: full synchronization.</li><li>If the permission scope has no intersection with the write path: no synchronization.</li><li>If the permission scope is smaller than the write path or overlaps partially: synchronize only the intersecting part.</li></ul></li><li><p>When encountering data for which the user lacks permission:</p><ul><li>If the sender’s skipIf=no‑privileges, the unauthorized data is skipped.</li><li>If skipIf is left empty (unconfigured), the task reports an error (Error 803).</li><li>Note: This skipIf configuration is independent of the receiver’s skipIf setting (which defaults to empty).</li></ul></li><li><p>Data under root.__system and root.__audit will not be synchronized.</p></li></ul><ol start="3"><li>Automatic Type Conversion for Pipe Sink</li></ol><p>When Pipe fails to write data to the sink due to field type mismatches, IoTDB automatically converts the data to the field types defined in the existing sink schema and retries the write operation to improve synchronization success rate. This feature is controlled by the parameter <code>sink.exception.data.convert-on-type-mismatch</code>. Refer to the subsequent sink parameter table for detailed parameter descriptions.</p><p>The conversion rules for type mismatches are as follows:</p><table><thead><tr><th>Source Type</th><th>Target Type</th><th>Conversion Rule</th></tr></thead><tbody><tr><td>Numeric Type</td><td>Numeric Type</td><td>Convert to the target numeric type. Truncation, precision loss or overflow may occur.</td></tr><tr><td>Numeric Type</td><td>BOOLEAN</td><td><code>0</code> is converted to <code>false</code>; non-zero values are converted to <code>true</code>.</td></tr><tr><td>BOOLEAN</td><td>Numeric Type</td><td><code>true</code> is converted to <code>1</code>; <code>false</code> is converted to <code>0</code>.</td></tr><tr><td>TEXT, STRING, BLOB</td><td>BOOLEAN</td><td>Parse the string into a BOOLEAN value.</td></tr><tr><td>TEXT, STRING, BLOB</td><td>Numeric Type</td><td>Parse the string into the target numeric type. If parsing fails, write the default value <code>0</code>, <code>0L</code> or <code>0.0</code>.</td></tr><tr><td>TEXT, STRING, BLOB</td><td>TIMESTAMP</td><td>Parse the string into a TIMESTAMP value. If parsing fails, write the default value <code>0L</code>.</td></tr><tr><td>TEXT, STRING, BLOB</td><td>DATE</td><td>Parse the string into a DATE value. If parsing fails, write the default date <code>1970-01-01</code>.</td></tr><tr><td>Invalid Numeric Value</td><td>DATE</td><td>If conversion to a valid DATE fails, write the default date <code>1970-01-01</code>.</td></tr><tr><td>DATE</td><td>TIMESTAMP</td><td>Convert to the timestamp of 00:00 (UTC) on the same day.</td></tr><tr><td>TIMESTAMP</td><td>DATE</td><td>Convert to the corresponding date in UTC.</td></tr></tbody></table><blockquote><p><strong>Note</strong>: Automatic conversion is performed based on the existing sink schema and will <strong>not</strong> modify the sink schema. This feature prioritizes continuous data synchronization, which may result in precision loss or writing of default values.</p></blockquote><h2 id="_2-usage-instructions" tabindex="-1"><a class="header-anchor" href="#_2-usage-instructions"><span>2. Usage Instructions</span></a></h2><p>Data synchronization tasks have three states: RUNNING, STOPPED, and DROPPED. The task state transitions are shown in the following diagram:</p><figure><img src="/img/Data-Sync02.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>After creation, the task will start directly, and when the task stops abnormally, the system will automatically attempt to restart the task.</p><p>Provide the following SQL statements for state management of synchronization tasks.</p><h3 id="_2-1-create-task" tabindex="-1"><a class="header-anchor" href="#_2-1-create-task"><span>2.1 Create Task</span></a></h3><p>Use the <code>CREATE PIPE</code> statement to create a data synchronization task. The <code>PipeId</code> and <code>sink</code> attributes are required, while <code>source</code> and <code>processor</code> are optional. When entering the SQL, note that the order of the <code>SOURCE</code> and <code>SINK</code> plugins cannot be swapped.</p><p>The SQL example is as follows:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> PIPE </span><span style="color:#E06C75;">[IF NOT EXISTS]</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span><span style="color:#7F848E;font-style:italic;"> -- PipeId is the name that uniquely identifies the task. </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Data extraction plugin, optional plugin</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SOURCE (</span></span>
<span class="line"><span style="color:#E06C75;">  [&lt;parameter&gt; = &lt;value&gt;,]</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Data processing plugin, optional plugin</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> PROCESSOR (</span></span>
<span class="line"><span style="color:#E06C75;">  [&lt;parameter&gt; = &lt;value&gt;,]</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Data connection plugin, required plugin</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#E06C75;">  [&lt;parameter&gt; = &lt;value&gt;,]</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>IF NOT EXISTS semantics</strong>: Used in creation operations to ensure that the create command is executed when the specified Pipe does not exist, preventing errors caused by attempting to create an existing Pipe.</p><p><strong>Note</strong>:</p><p>Starting from V2.0.8, when creating a full data synchronization Pipe (e.g. Pipeid: <code>alldatapipe</code>), the system will automatically split it into two independent Pipes:</p><ul><li>History Pipe: The PipeId is the original name plus the suffix <code>_history</code> (e.g. <code>alldatapipe_history</code>). The source parameter carries the default configurations: <code>&#39;realtime.enable&#39;=&#39;false&#39;, &#39;inclusion&#39;=&#39;data.insert&#39;, &#39;inclusion.exclusion&#39;=&#39;&#39;</code></li><li>Realtime Pipe: The PipeId is the original name plus the suffix <code>_realtime</code> (e.g. <code>alldatapipe_realtime</code>). The source parameter carries the default configuration: <code>&#39;history.enable&#39;=&#39;false&#39;</code>. If metadata synchronization is configured, the Realtime Pipe will be responsible for sending the data.</li></ul>`,32),i(`p`,null,[l[1]||=r(`After successful creation, the original PipeId (e.g. `,-1),l[2]||=i(`code`,null,`alldatapipe`,-1),l[3]||=r(`) will no longer be a valid identifier. When performing task operations such as starting, stopping, deleting, or viewing, you must use the split independent PipeId (i.e. `,-1),l[4]||=i(`code`,null,`*_history`,-1),l[5]||=r(` or `,-1),l[6]||=i(`code`,null,`*_realtime`,-1),l[7]||=r(`). For operation examples, see the `,-1),s(m,{to:`/UserGuide/latest/User-Manual/Data-Sync_apache.html#_2-5-view-task`},{default:t(()=>[...l[0]||=[r(`View Task`,-1)]]),_:1}),l[8]||=r(` section`,-1)]),l[13]||=c(`<h3 id="_2-2-start-task" tabindex="-1"><a class="header-anchor" href="#_2-2-start-task"><span>2.2 Start Task</span></a></h3><p>Start processing data:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">START</span><span style="color:#ABB2BF;"> PIPE</span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_2-3-stop-task" tabindex="-1"><a class="header-anchor" href="#_2-3-stop-task"><span>2.3 Stop Task</span></a></h3><p>Stop processing data:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">STOP</span><span style="color:#ABB2BF;"> PIPE </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_2-4-delete-task" tabindex="-1"><a class="header-anchor" href="#_2-4-delete-task"><span>2.4 Delete Task</span></a></h3><p>Deletes the specified task:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">DROP</span><span style="color:#ABB2BF;"> PIPE </span><span style="color:#E06C75;">[IF EXISTS]</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>IF EXISTS semantics</strong>: Used in deletion operations to ensure that when a specified Pipe exists, the delete command is executed to prevent errors caused by attempting to delete non-existent Pipes.</p><p>Deleting a task does not require stopping the synchronization task first.</p><h3 id="_2-5-view-task" tabindex="-1"><a class="header-anchor" href="#_2-5-view-task"><span>2.5 View Task</span></a></h3><p>View all tasks:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">SHOW PIPES</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>To view a specified task:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">SHOW PIPE </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Example of the show pipes result for a pipe:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------------+-----------------------+-------+----------+-------------+-----------------------------------------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                              ID|           CreationTime|  </span><span style="color:#C678DD;">State</span><span style="color:#ABB2BF;">|PipeSource|PipeProcessor|                                                   PipeSink|ExceptionMessage|RemainingEventCount|EstimatedRemainingSeconds|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------------+-----------------------+-------+----------+-------------+-----------------------------------------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|59abf95db892428b9d01c5fa318014ea|</span><span style="color:#D19A66;">2024</span><span style="color:#ABB2BF;">-</span><span style="color:#D19A66;">06</span><span style="color:#ABB2BF;">-17T14:</span><span style="color:#D19A66;">03</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">44</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">189</span><span style="color:#ABB2BF;">|RUNNING|        {}|           {}|{sink</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">iotdb-thrift-sink, </span><span style="color:#D19A66;">sink</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ip</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">127</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">sink</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">port</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">6668</span><span style="color:#ABB2BF;">}|                |                </span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">|                     </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">03</span><span style="color:#ABB2BF;">|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------------+-----------------------+-------+----------+-------------+-----------------------------------------------------------+----------------+-------------------+-------------------------+</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The meanings of each column are as follows:</p><ul><li><strong>ID</strong>：The unique identifier for the synchronization task</li><li><strong>CreationTime</strong>：The time when the synchronization task was created</li><li><strong>State</strong>：The state of the synchronization task</li><li><strong>PipeSource</strong>：The source of the synchronized data stream</li><li><strong>PipeProcessor</strong>：The processing logic of the synchronized data stream during transmission</li><li><strong>PipeSink</strong>：The destination of the synchronized data stream</li><li><strong>ExceptionMessage</strong>：Displays the exception information of the synchronization task</li><li><strong>RemainingEventCount (Statistics with Delay)</strong>: The number of remaining events, which is the total count of all events in the current data synchronization task, including data and schema synchronization events, as well as system and user-defined events.</li><li><strong>EstimatedRemainingSeconds (Statistics with Delay)</strong>: The estimated remaining time, based on the current number of events and the rate at the pipe, to complete the transfer.</li></ul><p>Example:</p><p>In V2.0.8 and later versions, create a full data synchronization task and view the task details.</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> create</span><span style="color:#ABB2BF;"> pipe alldatapipe </span><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> source(</span><span style="color:#98C379;">&#39;inclusion&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;all&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;exclusion&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;auth&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink(</span><span style="color:#98C379;">&#39;node-urls&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;"> show pipe alldatapipe_history</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+-----------------------+-------+---------------------------------------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                 ID|           CreationTime|  </span><span style="color:#C678DD;">State</span><span style="color:#ABB2BF;">|                                                                                               PipeSource|PipeProcessor|                  PipeSink|ExceptionMessage|RemainingEventCount|EstimatedRemainingSeconds|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+-----------------------+-------+---------------------------------------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|alldatapipe_history|</span><span style="color:#D19A66;">2025</span><span style="color:#ABB2BF;">-</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">-18T15:</span><span style="color:#D19A66;">06</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">16</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">697</span><span style="color:#ABB2BF;">|RUNNING|{exclusion</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">auth, </span><span style="color:#D19A66;">history</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">enable</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">true, inclusion</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">data</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">insert</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">inclusion</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">exclusion</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">realtime</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">enable</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">false}|           {}|{node-urls</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">127</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">6668</span><span style="color:#ABB2BF;">}|                |                  </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">|                     </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+-----------------------+-------+---------------------------------------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;"> show pipe alldatapipe_realtime</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------+-----------------------+-------+---------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                  ID|           CreationTime|  </span><span style="color:#C678DD;">State</span><span style="color:#ABB2BF;">|                                                                 PipeSource|PipeProcessor|                  PipeSink|ExceptionMessage|RemainingEventCount|EstimatedRemainingSeconds|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------+-----------------------+-------+---------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|alldatapipe_realtime|</span><span style="color:#D19A66;">2025</span><span style="color:#ABB2BF;">-</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">-18T15:</span><span style="color:#D19A66;">06</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">16</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">312</span><span style="color:#ABB2BF;">|RUNNING|{exclusion</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">auth, </span><span style="color:#D19A66;">history</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">enable</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">false, inclusion</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">all, </span><span style="color:#D19A66;">realtime</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">enable</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">true}|           {}|{node-urls</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">127</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">6668</span><span style="color:#ABB2BF;">}|                |                  </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">|                     </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------+-----------------------+-------+---------------------------------------------------------------------------+-------------+--------------------------+----------------+-------------------+-------------------------+</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-6-modify-task" tabindex="-1"><a class="header-anchor" href="#_2-6-modify-task"><span>2.6 Modify Task</span></a></h3><p>The <code>ALTER PIPE</code> statement dynamically updates an existing PIPE and supports modifying or replacing the configuration of source, processor, and sink.</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#ABB2BF;"> PIPE </span><span style="color:#E06C75;">[IF EXISTS]</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">PipeId</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#C678DD;">    MODIFY</span><span style="color:#ABB2BF;">/</span><span style="color:#C678DD;">REPLACE</span><span style="color:#ABB2BF;"> SOURCE(...)</span></span>
<span class="line"><span style="color:#C678DD;">    MODIFY</span><span style="color:#ABB2BF;">/</span><span style="color:#C678DD;">REPLACE</span><span style="color:#ABB2BF;"> PROCESSOR(...)</span></span>
<span class="line"><span style="color:#C678DD;">    MODIFY</span><span style="color:#ABB2BF;">/</span><span style="color:#C678DD;">REPLACE</span><span style="color:#ABB2BF;"> SINK(...)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Description:</p><ul><li>Executing this operation does not change the running state of the PIPE. It is equivalent to keeping the processing progress of the original PipeId and creating a new PIPE at the original progress position.</li><li>The modify/replace parameters for source/processor/sink are all optional. If no modification parameter is specified, it is equivalent to deleting the current PIPE and recreating it with the original configuration and progress.</li><li>For a plugin specified with modify, the plugin&#39;s other parameters are retained, and only the given parameters are replaced or added.</li><li>For a plugin specified with replace, all parameters of the plugin are replaced directly.</li><li>When the [IF EXISTS] keyword is used, execution succeeds even if no Pipe with the same name exists, but no operation is actually performed.</li></ul><p>Example:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#ABB2BF;"> PIPE A2B </span><span style="color:#C678DD;">REPLACE</span><span style="color:#ABB2BF;"> SINK (</span><span style="color:#98C379;">&#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_2-7-synchronization-plugins" tabindex="-1"><a class="header-anchor" href="#_2-7-synchronization-plugins"><span>2.7 Synchronization Plugins</span></a></h3><p>To make the overall architecture more flexible to match different synchronization scenario requirements, we support plugin assembly within the synchronization task framework. The system comes with some pre-installed common plugins that you can use directly. At the same time, you can also customize processor plugins and Sink plugins, and load them into the IoTDB system for use. You can view the plugins in the system (including custom and built-in plugins) with the following statement:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">SHOW PIPEPLUGINS</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>The return result is as follows (version 1.3.2):</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;"> SHOW PIPEPLUGINS</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------------+----------+--------------------------------------------------------------------------------------------------+----------------------------------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                    PluginName|PluginType|                                                                                         ClassName|                                           PluginJar|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------------+----------+--------------------------------------------------------------------------------------------------+----------------------------------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|          DO-NOTHING-PROCESSOR|   Builtin|               </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">processor</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">donothing</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DoNothingProcessor</span><span style="color:#ABB2BF;">|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">|               DO-NOTHING-SINK|   Builtin|               </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">connector</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">donothing</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DoNothingConnector</span><span style="color:#ABB2BF;">|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">|                  IOTDB-SOURCE|   Builtin|                       </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">extractor</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">IoTDBExtractor</span><span style="color:#ABB2BF;">|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">|             IOTDB-THRIFT-SINK|   Builtin|          </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">connector</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">thrift</span><span style="color:#ABB2BF;">.IoTDBThriftConnector|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">|         IOTDB-THRIFT-</span><span style="color:#C678DD;">SSL</span><span style="color:#ABB2BF;">-SINK|   Builtin|       </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">commons</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pipe</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plugin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">builtin</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">connector</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">thrift</span><span style="color:#ABB2BF;">.IoTDBThriftSslConnector|                                                    |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------------+----------+--------------------------------------------------------------------------------------------------+----------------------------------------------------+</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Detailed introduction of pre-installed plugins is as follows (for detailed parameters of each plugin, please refer to the <a href="#reference-parameter-description">Parameter Description</a> section):</p><table style="text-align:left;"><tbody><tr><th>Type</th><th>Custom Plugin</th><th>Plugin Name</th><th>Description</th><th>Applicable Version</th></tr><tr><td>source plugin</td><td>Not Supported</td><td>iotdb-source</td><td>The default extractor plugin, used to extract historical or real-time data from IoTDB</td><td>1.2.x</td></tr><tr><td>processor plugin</td><td>Supported</td><td>do-nothing-processor</td><td>The default processor plugin, which does not process the incoming data</td><td>1.2.x</td></tr><tr><td rowspan="3">sink plugin</td><td rowspan="3">Supported</td><td>do-nothing-sink</td><td>Does not process the data that is sent out</td><td>1.2.x</td></tr><tr><td>iotdb-thrift-sink</td><td>The default sink plugin ( V1.3.1+ ), used for data transfer between IoTDB ( V1.2.0+ ) and IoTDB( V1.2.0+ ) . It uses the Thrift RPC framework to transfer data, with a multi-threaded async non-blocking IO model, high transfer performance, especially suitable for scenarios where the target end is distributed</td><td>1.2.x</td></tr><tr><td>iotdb-thrift-ssl-sink</td><td>Used for data transfer between IoTDB ( V1.3.1+ ) and IoTDB ( V1.2.0+ ). It uses the Thrift RPC framework to transfer data, with a single-threaded sync blocking IO model, suitable for scenarios with higher security requirements</td><td>1.3.1+</td></tr></tbody></table>`,37),i(`p`,null,[l[10]||=r(`For importing custom plugins, please refer to the `,-1),s(m,{to:`/UserGuide/latest/User-Manual/Streaming_apache.html#custom-stream-processing-plugin-management`},{default:t(()=>[...l[9]||=[r(`Stream Processing`,-1)]]),_:1}),l[11]||=r(` section.`,-1)]),l[14]||=c(`<h2 id="_3-use-examples" tabindex="-1"><a class="header-anchor" href="#_3-use-examples"><span>3. Use examples</span></a></h2><h3 id="_3-1-full-data-synchronisation" tabindex="-1"><a class="header-anchor" href="#_3-1-full-data-synchronisation"><span>3.1 Full data synchronisation</span></a></h3><p>This example is used to demonstrate the synchronisation of all data from one IoTDB to another IoTDB with the data link as shown below:</p><figure><img src="/img/pipe1.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>In this example, we can create a synchronization task named A2B to synchronize the full data from A IoTDB to B IoTDB. The iotdb-thrift-sink plugin (built-in plugin) for the sink is required. The URL of the data service port of the DataNode node on the target IoTDB needs to be configured through node-urls, as shown in the following example statement:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe A2B</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">,</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-partial-data-synchronization" tabindex="-1"><a class="header-anchor" href="#_3-2-partial-data-synchronization"><span>3.2 Partial data synchronization</span></a></h3><p>This example is used to demonstrate the synchronisation of data from a certain historical time range (8:00pm 23 August 2023 to 8:00pm 23 October 2023) to another IoTDB, the data link is shown below:</p><figure><img src="/img/pipe2.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>In this example, we can create a synchronization task named A2B. First, we need to define the range of data to be transferred in the source. Since the data being transferred is historical data (historical data refers to data that existed before the creation of the synchronization task), we need to configure the start-time and end-time of the data and the transfer mode mode. The URL of the data service port of the DataNode node on the target IoTDB needs to be configured through node-urls.</p><p>The detailed statements are as follows:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe A2B</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> SOURCE (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;source&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;iotdb-source&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;realtime.mode&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;stream&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;path&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;root.vehicle.**&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;start-time&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;2023.08.23T08:00:00+00:00&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;end-time&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;2023.10.23T08:00:00+00:00&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">) </span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> SINK (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-async-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Where:</p><ul><li><code>realtime.mode</code>: The extraction mode for newly inserted data (after pipe creation)</li><li><code>path</code>: Scope of Data Synchronization</li><li><code>start-time</code>: The start event time for synchronizing all data, including start-time</li><li><code>end-time</code>: The end event time for synchronizing all data, including end-time</li></ul><h3 id="_3-3-edge-cloud-data-transfer" tabindex="-1"><a class="header-anchor" href="#_3-3-edge-cloud-data-transfer"><span>3.3 Edge-cloud data transfer</span></a></h3><p>This example is used to demonstrate the scenario where data from multiple IoTDB is transferred to the cloud, with data from clusters B, C, and D all synchronized to cluster A, as shown in the figure below:</p><figure><img src="/img/sync_en_03.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>In this example, to synchronize the data from clusters B, C, and D to A, the pipe between BA, CA, and DA needs to configure the <code>path</code> to limit the range, and to keep the edge and cloud data consistent, the pipe needs to be configured with <code>inclusion=all</code> to synchronize full data and metadata. The detailed statement is as follows:</p><p>On B IoTDB, execute the following statement to synchronize data from B to A:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe BA</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> source (</span></span>
<span class="line"><span style="color:#98C379;">   &#39;inclusion&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;all&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">   &#39;path&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;root.db.**&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>On C IoTDB, execute the following statement to synchronize data from C to A:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe CA</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> source (</span></span>
<span class="line"><span style="color:#98C379;">   &#39;inclusion&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;all&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">   &#39;path&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;root.db.**&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>On D IoTDB, execute the following statement to synchronize data from D to A:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe DA</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> source (</span></span>
<span class="line"><span style="color:#98C379;">   &#39;inclusion&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;all&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">   &#39;path&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;root.db.**&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The parameters in the preceding two examples have the same meanings as those below:</p><ul><li><code>inclusion</code>: Indicates synchronization of full data, schema , and auth</li><li><code>path</code>: Limit the range</li><li><code>node-urls</code>: The URL of the data service port of the DataNode node on the target IoTDB</li></ul><h3 id="_3-4-cascading-data-transfer" tabindex="-1"><a class="header-anchor" href="#_3-4-cascading-data-transfer"><span>3.4 Cascading data transfer</span></a></h3><p>This example is used to demonstrate the scenario where data is transferred in a cascading manner between multiple IoTDB, with data from cluster A synchronized to cluster B, and then to cluster C, as shown in the figure below:</p><figure><img src="/img/sync_en_04.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>In this example, to synchronize the data from cluster A to C, the <code>forwarding-pipe-requests</code> needs to be set to <code>true</code> between BC. The detailed statement is as follows:</p><p>On A IoTDB, execute the following statement to synchronize data from A to B:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe AB</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>On B IoTDB, execute the following statement to synchronize data from B to C:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe BC</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> source (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;forwarding-pipe-requests&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;true&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6669&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The <code>node-urls</code> parameter in the preceding example has the same meaning as below:</p><ul><li><code>forwarding-pipe-requests</code>: Whether to forward data written by other Pipes</li><li><code>node-urls</code>: The URL of the data service port of the DataNode node on the target IoTDB</li></ul><h3 id="_3-5-compression-synchronization-v1-3-3" tabindex="-1"><a class="header-anchor" href="#_3-5-compression-synchronization-v1-3-3"><span>3.5 Compression Synchronization (V1.3.3+)</span></a></h3><p>IoTDB supports specifying data compression methods during synchronization. Real time compression and transmission of data can be achieved by configuring the <code>compressor</code> parameter. <code>Compressor</code> currently supports 5 optional algorithms: snappy/gzip/lz4/zstd/lzma2, and can choose multiple compression algorithm combinations to compress in the order of configuration <code>rate-limit-bytes-per-second</code>(supported in V1.3.3 and later versions) is the maximum number of bytes allowed to be transmitted per second, calculated as compressed bytes. If it is less than 0, there is no limit.</p><p>For example, to create a synchronization task named A2B:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe A2B </span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink (</span></span>
<span class="line"><span style="color:#98C379;"> &#39;node-urls&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;127.0.0.1:6668&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;"> &#39;compressor&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;snappy,lz4&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Where:</p><ul><li><code>node-urls</code>: The URL of the data service port of the DataNode node on the target IoTDB</li></ul><h3 id="_3-6-encrypted-synchronization-v1-3-1" tabindex="-1"><a class="header-anchor" href="#_3-6-encrypted-synchronization-v1-3-1"><span>3.6 Encrypted Synchronization (V1.3.1+)</span></a></h3><p>IoTDB supports the use of SSL encryption during the synchronization process, ensuring the secure transfer of data between different IoTDB instances. By configuring SSL-related parameters, such as the certificate address and password （<code>ssl.trust-store-path</code>）、（<code>ssl.trust-store-pwd</code>）, data can be protected by SSL encryption during the synchronization process.</p><p>For example, to create a synchronization task named A2B:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">create</span><span style="color:#ABB2BF;"> pipe A2B</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> sink (</span></span>
<span class="line"><span style="color:#98C379;">  &#39;sink&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;iotdb-thrift-ssl-sink&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;node-urls&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;127.0.0.1:6667&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;ssl.trust-store-path&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;pki/trusted&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">  &#39;ssl.trust-store-pwd&#39;</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;root&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Where:</p><ul><li><code>node-urls</code>: The URL of the data service port of the DataNode node on the target IoTDB</li><li><code>ssl.trust-store-path</code>: The trust store certificate path required to connect to the target DataNode</li><li><code>ssl.trust-store-pwd</code>: The trust store certificate password required to connect to the target DataNode</li></ul><h2 id="_4-reference-notes" tabindex="-1"><a class="header-anchor" href="#_4-reference-notes"><span>4. Reference: Notes</span></a></h2><p>You can adjust the parameters for data synchronization by modifying the IoTDB configuration file （<code>iotdb-system.properties</code>）, such as the directory for storing synchronized data. The complete configuration is as follows:</p><p>V1.3.3+:</p><div class="language-properties line-numbers-mode" data-highlighter="shiki" data-ext="properties" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-properties"><span class="line"><span style="color:#7F848E;font-style:italic;"># pipe_receiver_file_dir</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If this property is unset, system will save the data in the default relative path directory under the IoTDB folder(i.e., %IOTDB_HOME%/\${cn_system_dir}/pipe/receiver).</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If it is absolute, system will save the data in the exact location it points to.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If it is relative, system will save the data in the relative path directory it indicates under the IoTDB folder.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Note: If pipe_receiver_file_dir is assigned an empty string(i.e.,zero-size), it will be handled as a relative path.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># For windows platform</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If its prefix is a drive specifier followed by &quot;\\\\&quot;, or if its prefix is &quot;\\\\\\\\&quot;, then the path is absolute. Otherwise, it is relative.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># pipe_receiver_file_dir=data\\\\confignode\\\\system\\\\pipe\\\\receiver</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># For Linux platform</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If its prefix is &quot;/&quot;, then the path is absolute. Otherwise, it is relative.</span></span>
<span class="line"><span style="color:#C678DD;">pipe_receiver_file_dir</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">data/confignode/system/pipe/receiver</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">####################</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">### Pipe Configuration</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">####################</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Uncomment the following field to configure the pipe lib directory.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: first_start</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># For Windows platform</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If its prefix is a drive specifier followed by &quot;\\\\&quot;, or if its prefix is &quot;\\\\\\\\&quot;, then the path is</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># absolute. Otherwise, it is relative.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># pipe_lib_dir=ext\\\\pipe</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># For Linux platform</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If its prefix is &quot;/&quot;, then the path is absolute. Otherwise, it is relative.</span></span>
<span class="line"><span style="color:#C678DD;">pipe_lib_dir</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">ext/pipe</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The maximum number of threads that can be used to execute the pipe subtasks in PipeSubtaskExecutor.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The actual value will be min(pipe_subtask_executor_max_thread_num, max(1, CPU core number / 2)).</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: int</span></span>
<span class="line"><span style="color:#C678DD;">pipe_subtask_executor_max_thread_num</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">5</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The connection timeout (in milliseconds) for the thrift client.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: int</span></span>
<span class="line"><span style="color:#C678DD;">pipe_sink_timeout_ms</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">900000</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The maximum number of selectors that can be used in the sink.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Recommend to set this value to less than or equal to pipe_sink_max_client_number.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: int</span></span>
<span class="line"><span style="color:#C678DD;">pipe_sink_selector_number</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">4</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The maximum number of clients that can be used in the sink.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: restart</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: int</span></span>
<span class="line"><span style="color:#C678DD;">pipe_sink_max_client_number</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">16</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># The total bytes that all pipe sinks can transfer per second.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># When given a value less than or equal to 0, it means no limit.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># default value is -1, which means no limit.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effectiveMode: hot_reload</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Datatype: double</span></span>
<span class="line"><span style="color:#C678DD;">pipe_all_sinks_rate_limit_bytes_per_second</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">-1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-reference-parameter-description" tabindex="-1"><a class="header-anchor" href="#_5-reference-parameter-description"><span>5. Reference: parameter description</span></a></h2><h3 id="_5-1-source-parameter" tabindex="-1"><a class="header-anchor" href="#_5-1-source-parameter"><span>5.1 source parameter</span></a></h3><table><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Value</th><th style="text-align:left;">Value range</th><th style="text-align:left;">Required</th><th style="text-align:left;">Default value</th></tr></thead><tbody><tr><td style="text-align:left;">source</td><td style="text-align:left;">iotdb-source</td><td style="text-align:left;">String: iotdb-source</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">inclusion</td><td style="text-align:left;">Used to specify the range of data to be synchronized in the data synchronization task, including data, schema, and auth</td><td style="text-align:left;">String:all, data(insert,delete), schema(database,timeseries,ttl), auth</td><td style="text-align:left;">No</td><td style="text-align:left;">data.insert</td></tr><tr><td style="text-align:left;">inclusion.exclusion</td><td style="text-align:left;">Used to exclude specific operations from the range specified by inclusion, reducing the amount of data synchronized</td><td style="text-align:left;">String:all, data(insert,delete), schema(database,timeseries,ttl), auth</td><td style="text-align:left;">No</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">mode.streaming</td><td style="text-align:left;">Specifies the capture source for time-series data writes. Applicable when mode.streamingis false, determining the source for capturing data.insertspecified in inclusion. Offers two strategies:- true: ​​Dynamic capture selection.​​ The system adaptively chooses between capturing individual write requests or only TsFile sealing requests based on downstream processing speed. Prioritizes capturing write requests for lower latency when processing is fast; captures only file sealing requests to avoid backlog when slow. Suitable for most scenarios, balancing latency and throughput optimally.- false: ​​Fixed batch capture.​​ Captures only TsFile sealing requests. Suitable for resource-constrained scenarios to reduce system load. Note: The snapshot data captured upon pipe startup is only provided to downstream processing in file format.</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">mode.strict</td><td style="text-align:left;">Determines the strictness when filtering data using time/ path/ database-name/ table-nameparameters:- true: ​​Strict filtering.​​ The system strictly filters captured data according to the given conditions, ensuring only matching data is selected.- false: ​​Non-strict filtering.​​ The system may include some extra data during filtering. Suitable for performance-sensitive scenarios to reduce CPU and I/O consumption.</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">mode.snapshot</td><td style="text-align:left;">Determines the capture mode for time-series data, affecting the dataspecified in inclusion. Offers two modes:- true: ​​Static data capture.​​ Upon pipe startup, a one-time data snapshot is captured. ​​The pipe will automatically terminate (DROP PIPE SQL is executed automatically) after the snapshot data is fully consumed.​​- false: ​​Dynamic data capture.​​ In addition to capturing a snapshot upon startup, the pipe continuously captures subsequent data changes. The pipe runs continuously to handle the dynamic data stream.</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">false</td></tr><tr><td style="text-align:left;">path</td><td style="text-align:left;">Can be specified when the user connects with sql_dialectset to tree. For upgraded user pipes, the default sql_dialectis tree. This parameter determines the capture scope for time-series data, affecting the dataspecified in inclusion, as well as some sequence-related metadata. Data is selected into the streaming pipe if its tree model path matches the specified path. <br> Starting from version V2.0.8, this parameter supports specifying multiple exact paths in a single pipe, e.g., <code>&#39;path&#39;=&#39;root.test.d0.s1,root.test.d0.s2,root.test.d0.s3&#39;</code>.</td><td style="text-align:left;">String: IoTDB-standard tree path pattern, wildcards allowed</td><td style="text-align:left;">No</td><td style="text-align:left;">root.**</td></tr><tr><td style="text-align:left;">start-time</td><td style="text-align:left;">The start event time for synchronizing all data, including start-time</td><td style="text-align:left;">Long: [Long.MIN_VALUE, Long.MAX_VALUE]</td><td style="text-align:left;">No</td><td style="text-align:left;">Long.MIN_VALUE</td></tr><tr><td style="text-align:left;">end-time</td><td style="text-align:left;">The end event time for synchronizing all data, including end-time</td><td style="text-align:left;">Long: [Long.MIN_VALUE, Long.MAX_VALUE]</td><td style="text-align:left;">No</td><td style="text-align:left;">Long.MAX_VALUE</td></tr><tr><td style="text-align:left;">forwarding-pipe-requests</td><td style="text-align:left;">Whether to forward data written by other Pipes (usually data synchronization)</td><td style="text-align:left;">Boolean: true /false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">mods</td><td style="text-align:left;">Same as mods.enable, whether to send the MODS file for TSFile.</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">false</td></tr><tr><td style="text-align:left;">skipIf</td><td style="text-align:left;">Which errors can be skipped? Currently only the insufficient privileges error.</td><td style="text-align:left;">String:no-privileges</td><td style="text-align:left;">No</td><td style="text-align:left;">no-privileges</td></tr></tbody></table><blockquote><p>💎 <strong>Note:</strong> The difference between the values of true and false for the data extraction mode <code>mode.streaming</code></p><ul><li>True (recommended): Under this value, the task will process and send the data in real-time. Its characteristics are high timeliness and low throughput.</li><li>False: Under this value, the task will process and send the data in batches (according to the underlying data files). Its characteristics are low timeliness and high throughput.</li></ul></blockquote><h3 id="_5-2-sink-parameter" tabindex="-1"><a class="header-anchor" href="#_5-2-sink-parameter"><span>5.2 sink parameter</span></a></h3><h4 id="iotdb-thrift-sink" tabindex="-1"><a class="header-anchor" href="#iotdb-thrift-sink"><span>iotdb-thrift-sink</span></a></h4><table><thead><tr><th style="text-align:left;"><strong>Parameter</strong></th><th style="text-align:left;"><strong>Description</strong></th><th style="text-align:left;">Value Range</th><th style="text-align:left;">Required</th><th style="text-align:left;">Default Value</th></tr></thead><tbody><tr><td style="text-align:left;">sink</td><td style="text-align:left;">iotdb-thrift-sink or iotdb-thrift-async-sink</td><td style="text-align:left;">String: iotdb-thrift-sink or iotdb-thrift-async-sink</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">node-urls</td><td style="text-align:left;">URLs of the DataNode service ports on the target IoTDB. (please note that the synchronization task does not support forwarding to its own service).</td><td style="text-align:left;">String. Example：&#39;127.0.0.1：6667，127.0.0.1：6668，127.0.0.1：6669&#39;， &#39;127.0.0.1：6667&#39;</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">user/username</td><td style="text-align:left;">Username for connecting to the target IoTDB. Must have appropriate permissions.</td><td style="text-align:left;">String</td><td style="text-align:left;">No</td><td style="text-align:left;">root</td></tr><tr><td style="text-align:left;">password</td><td style="text-align:left;">Password for the username.</td><td style="text-align:left;">String</td><td style="text-align:left;">No</td><td style="text-align:left;">root</td></tr><tr><td style="text-align:left;">batch.enable</td><td style="text-align:left;">Enables batch mode for log transmission to improve throughput and reduce IOPS.</td><td style="text-align:left;">Boolean: true, false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">batch.max-delay-seconds</td><td style="text-align:left;">Maximum delay (in seconds) for batch transmission.</td><td style="text-align:left;">Integer</td><td style="text-align:left;">No</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">batch.max-delay-ms</td><td style="text-align:left;">Maximum delay (in ms) for batch transmission. (Available since v2.0.5)</td><td style="text-align:left;">Integer</td><td style="text-align:left;">No</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">batch.size-bytes</td><td style="text-align:left;">Maximum batch size (in bytes) for batch transmission.</td><td style="text-align:left;">Long</td><td style="text-align:left;">No</td><td style="text-align:left;">16<em>1024</em>1024</td></tr><tr><td style="text-align:left;">compressor</td><td style="text-align:left;">The selected RPC compression algorithm. Multiple algorithms can be configured and will be adopted in sequence for each request.</td><td style="text-align:left;">String: snappy / gzip / lz4 / zstd / lzma2</td><td style="text-align:left;">No</td><td style="text-align:left;">&quot;&quot;</td></tr><tr><td style="text-align:left;">compressor.zstd.level</td><td style="text-align:left;">When the selected RPC compression algorithm is zstd, this parameter can be used to additionally configure the compression level of the zstd algorithm.</td><td style="text-align:left;">Int: [-131072, 22]</td><td style="text-align:left;">No</td><td style="text-align:left;">3</td></tr><tr><td style="text-align:left;">rate-limit-bytes-per-second</td><td style="text-align:left;">The maximum number of bytes allowed to be transmitted per second. The compressed bytes (such as after compression) are calculated. If it is less than 0, there is no limit.</td><td style="text-align:left;">Double: [Double.MIN_VALUE, Double.MAX_VALUE]</td><td style="text-align:left;">No</td><td style="text-align:left;">-1</td></tr><tr><td style="text-align:left;">load-tsfile-strategy</td><td style="text-align:left;">When synchronizing file data, ​​whether the receiver waits for the local load tsfile operation to complete before responding to the sender​​:<br>​​sync​​: Wait for the local load tsfile operation to complete before returning the response.<br>​​async​​: Do not wait for the local load tsfile operation to complete; return the response immediately.</td><td style="text-align:left;">String: sync / async</td><td style="text-align:left;">No</td><td style="text-align:left;">sync</td></tr><tr><td style="text-align:left;">format</td><td style="text-align:left;">The payload formats for data transmission include the following options:<br> - hybrid: The format depends on what is passed from the processor (either tsfile or tablet), and the sink performs no conversion.<br> - tsfile: Data is forcibly converted to tsfile format before transmission. This is suitable for scenarios like data file backup.<br> - tablet: Data is forcibly converted to tsfile format before transmission. This is useful for data synchronization when the sender and receiver have incompatible data types (to minimize errors).</td><td style="text-align:left;">String: hybrid / tsfile / tablet</td><td style="text-align:left;">No</td><td style="text-align:left;">hybrid</td></tr><tr><td style="text-align:left;">exception.data.convert-on-type-mismatch</td><td style="text-align:left;">Whether to enable automatic conversion when data types mismatch on the sink side</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr></tbody></table><h4 id="iotdb-thrift-ssl-sink" tabindex="-1"><a class="header-anchor" href="#iotdb-thrift-ssl-sink"><span>iotdb-thrift-ssl-sink</span></a></h4><table><thead><tr><th style="text-align:left;"><strong>Parameter</strong></th><th style="text-align:left;"><strong>Description</strong></th><th style="text-align:left;">Value Range</th><th style="text-align:left;">Required</th><th style="text-align:left;">Default Value</th></tr></thead><tbody><tr><td style="text-align:left;">sink</td><td style="text-align:left;">iotdb-thrift-ssl-sink</td><td style="text-align:left;">String: iotdb-thrift-ssl-sink</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">node-urls</td><td style="text-align:left;">URLs of the DataNode service ports on the target IoTDB. (please note that the synchronization task does not support forwarding to its own service).</td><td style="text-align:left;">String. Example：&#39;127.0.0.1：6667，127.0.0.1：6668，127.0.0.1：6669&#39;， &#39;127.0.0.1：6667&#39;</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">user/username</td><td style="text-align:left;">Username for connecting to the target IoTDB. Must have appropriate permissions.</td><td style="text-align:left;">String</td><td style="text-align:left;">No</td><td style="text-align:left;">root</td></tr><tr><td style="text-align:left;">password</td><td style="text-align:left;">Password for the username.</td><td style="text-align:left;">String</td><td style="text-align:left;">No</td><td style="text-align:left;">root</td></tr><tr><td style="text-align:left;">batch.enable</td><td style="text-align:left;">Enables batch mode for log transmission to improve throughput and reduce IOPS.</td><td style="text-align:left;">Boolean: true, false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr><tr><td style="text-align:left;">batch.max-delay-seconds</td><td style="text-align:left;">Maximum delay (in seconds) for batch transmission.</td><td style="text-align:left;">Integer</td><td style="text-align:left;">No</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">batch.max-delay-ms</td><td style="text-align:left;">Maximum delay (in ms) for batch transmission. (Available since v2.0.5)</td><td style="text-align:left;">Integer</td><td style="text-align:left;">No</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">batch.size-bytes</td><td style="text-align:left;">Maximum batch size (in bytes) for batch transmission.</td><td style="text-align:left;">Long</td><td style="text-align:left;">No</td><td style="text-align:left;">16<em>1024</em>1024</td></tr><tr><td style="text-align:left;">compressor</td><td style="text-align:left;">The selected RPC compression algorithm. Multiple algorithms can be configured and will be adopted in sequence for each request.</td><td style="text-align:left;">String: snappy / gzip / lz4 / zstd / lzma2</td><td style="text-align:left;">No</td><td style="text-align:left;">&quot;&quot;</td></tr><tr><td style="text-align:left;">compressor.zstd.level</td><td style="text-align:left;">When the selected RPC compression algorithm is zstd, this parameter can be used to additionally configure the compression level of the zstd algorithm.</td><td style="text-align:left;">Int: [-131072, 22]</td><td style="text-align:left;">No</td><td style="text-align:left;">3</td></tr><tr><td style="text-align:left;">rate-limit-bytes-per-second</td><td style="text-align:left;">Maximum bytes allowed per second for transmission (calculated after compression). Set to a value less than 0 for no limit.</td><td style="text-align:left;">Double: [Double.MIN_VALUE, Double.MAX_VALUE]</td><td style="text-align:left;">No</td><td style="text-align:left;">-1</td></tr><tr><td style="text-align:left;">load-tsfile-strategy</td><td style="text-align:left;">When synchronizing file data, ​​whether the receiver waits for the local load tsfile operation to complete before responding to the sender​​:<br>​​sync​​: Wait for the local load tsfile operation to complete before returning the response.<br>​​async​​: Do not wait for the local load tsfile operation to complete; return the response immediately.</td><td style="text-align:left;">String: sync / async</td><td style="text-align:left;">No</td><td style="text-align:left;">sync</td></tr><tr><td style="text-align:left;">ssl.trust-store-path</td><td style="text-align:left;">Path to the trust store certificate for SSL connection.</td><td style="text-align:left;">String: &#39;pki/trusted&#39;</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">ssl.trust-store-pwd</td><td style="text-align:left;">Password for the trust store certificate.</td><td style="text-align:left;">String: &#39;root&#39;</td><td style="text-align:left;">Yes</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">format</td><td style="text-align:left;">The payload formats for data transmission include the following options:<br> - hybrid: The format depends on what is passed from the processor (either tsfile or tablet), and the sink performs no conversion.<br> - tsfile: Data is forcibly converted to tsfile format before transmission. This is suitable for scenarios like data file backup.<br> - tablet: Data is forcibly converted to tsfile format before transmission. This is useful for data synchronization when the sender and receiver have incompatible data types (to minimize errors).</td><td style="text-align:left;">String: hybrid / tsfile / tablet</td><td style="text-align:left;">No</td><td style="text-align:left;">hybrid</td></tr><tr><td style="text-align:left;">exception.data.convert-on-type-mismatch</td><td style="text-align:left;">Whether to enable automatic conversion when data types mismatch on the sink side</td><td style="text-align:left;">Boolean: true / false</td><td style="text-align:left;">No</td><td style="text-align:left;">true</td></tr></tbody></table>`,61)])}var f=a(u,[[`render`,d]]);export{l as _pageData,f as default};